	[1421] = {
		name = "银松森林",
		short = "银松森林，或简称银松，是一片沿着洛丹伦崎岖的西部海岸绵延的古老森林。这里的地势从较为平坦到丘陵起伏不等，四周环绕着更为高耸的群山。",
		full = "银松森林，或简称银松，是一片沿着洛丹伦崎岖的西部海岸绵延的古老森林。这里的地势从较为平坦到丘陵起伏不等，四周环绕着更为高耸的群山。森林中一片死寂，只是偶尔会有诡异的嚎叫声在林间回荡。长满苔藓的崖檐在寒风中瑟瑟发抖，树木全都病恹恹的，或正在死去。破败的农庄和废弃的矿井散落各处，如今已成为林中更加黑暗的居民的巢穴。\n\n这片林地鬼影幢幢、荒凉野性，最显著的特征便是那些高耸于长满青草的小丘之上、树皮银白的松树。在这里还生机盎然、郁郁葱葱的时候，联盟曾守护着银松森林。如今这里却笼罩在鬼魅般的迷雾之中。被遗忘者控制着森林北部，不断与卑劣的腐皮豺狼人发生冲突。残存的人类仍控制着森林南部，但他们已陷入绝境，兵力也捉襟见肘。达拉然频繁地派遣远征队进入银松森林，保护这些人，并研究亡灵瘟疫和狼人诅咒。这是一种神秘的痛苦折磨，每当月亮升起，受害者就会变成嗜血的狼人。\n\n吉尔尼斯和希尔斯布莱德丘陵在森林的南面与之接壤，而提瑞斯法林地位于北面。洛丹米尔湖则是银松森林的东部边界。\n\n尽管这片领土属于被遗忘者，但他们的主权却受到达拉然法师和天灾军团爪牙的挑战，后者占据了一些荒废的田地和农庄。腐皮豺狼人以神秘的芬里斯岛为据点，凶狠地攻击任何胆敢靠近他们勾当的人。西南部坐落着焚木村，村民们中了大法师阿鲁高的诅咒，每到夜晚便会变成嗜血的狼人。阿鲁高本人则盘踞在附近影牙城堡那阴暗的高塔之中。\n\n银松森林战事频仍，因为来自南海镇的联盟军队常常深入这片被遗弃的森林，进攻瑟伯切尔或闯入影牙城堡。这里是被遗忘者家园的边缘，也是在植物身上还能看到亡灵瘟疫影响的最南端。",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "西瘟疫之地",
		short = "这里曾是洛丹伦北部最美丽的农田，森林茂密，绿意盎然，从安多哈尔供养着王国的粮仓，并由壁炉谷的大厅统辖。",
		full = "这里曾是洛丹伦北部最美丽的农田，森林茂密，绿意盎然，从安多哈尔供养着王国的粮仓，并由壁炉谷的大厅统辖。而正是这份富庶，成了摧毁它的武器。\n\n按照巫妖王的计划，诅咒神教用便携式的大锅将他的瘟疫能量运往南方，藏在忠于他们的教徒村庄里，并把最大的四口大锅安放在安多哈尔自己的田地上。粮食本身遭到了污染，被装上马车运往洛丹伦各地，却无人想到要去查问。吃下自家面包的人们纷纷病倒、死去，又作为巫妖王的奴仆重新站了起来。森林再也没能恢复。松树在病态的雾霭下灰白一片，针叶枯黄，树干上长满了肿瘤般的赘生物。\n\n如今残存的些许秩序，是在王国崩溃之后挽救下来的：当时血色十字军占领了壁炉谷的玛登霍尔德城堡，并以那里为据点，出击攻打盘踞在其余土地上的亡灵。在这一切之中，只有一处地方还保有些许安宁：那就是乌瑟尔之墓，它被献给光明使者乌瑟尔，是一片从未被枯萎之力触及的土地。",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "东瘟疫之地",
		short = "这里的土地曾是一片农田，东威尔德的村庄散布在洛丹伦第二大城市斯坦索姆的周围。这一切如今都已荡然无存。",
		full = "这里的土地曾是一片农田，东威尔德的村庄散布在洛丹伦第二大城市斯坦索姆的周围。这一切如今都已荡然无存。土壤变得褐黄病态，树木膨胀成了巨大的蘑菇，空气中弥漫着浓重的橙色雾气。\n\n正是在斯坦索姆，阿尔萨斯王子前来追寻一场瘟疫的源头，而那场瘟疫早已夺去了镇民们的生命。白银之手的领袖乌瑟尔大人拒绝让他清洗这座城市。阿尔萨斯当即解除了他的指挥权，就地解散了白银之手，并亲自将斯坦索姆的居民屠戮殆尽，而不愿让他们复活成为天灾军团的爪牙。他并未就此罢手：他将恐惧魔王玛尔加尼斯一路追到北方，归来时已成为一名死亡骑士，并亲手杀死了自己的父亲，终结了洛丹伦王国。\n\n亚历山德罗斯·莫格莱尼从白银之手的残部中组建起一支十字军，力图收复这片废墟，他夺下了提尔之手和半座斯坦索姆，直到他的死令他的组织分裂为银色黎明和血色十字军。后者至今仍占据着这片土地，与天灾军团无休止地作战，也不欢迎任何外人。",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "希尔斯布莱德丘陵",
		short = "希尔斯布莱德的土壤肥沃，山丘青翠，旅人们说，在瘟疫来临之前，整个洛丹伦都是这般模样。",
		full = "希尔斯布莱德的土壤肥沃，山丘青翠，旅人们说，在瘟疫来临之前，整个洛丹伦都是这般模样。这既是它的慰藉，也是它的残酷之处：这片土地记得其他各处所失去的一切，而占据此地的人们仍在进行着那场毁灭了其余一切的战争。\n\n第二次战争伊始，兽人袭击者洗劫了这里的沿海城镇，奥格瑞姆·毁灭之锤亲自率军攻打敦霍尔德城堡，将祖尔金从牢房中解救出来。数十年后，穿过这片丘陵的则是萨尔，他召集起四散的兽人氏族，然后趁着夜色潜入南海镇，偷走那里的船只，载着新部落渡海前往卡利姆多。\n\n兽人开了头的事，被遗忘者接着做了下去。他们占据了塔伦米尔，将其作为自己最南端的据点，并把它变成了对付南海镇和希尔斯布莱德农场人类的集结地，而那些人类一直坚定地为联盟守卫着这片土地。\n\n如今，松林点缀在农田之间，道路依然穿过牧场，通往北方阴郁的被遗忘者定居点，仿佛这片土地本身仍在等待，看哪一方最终能将它留住。",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "辛特兰",
		short = "三锤之战后，蛮锤矮人放弃了他们在格瑞姆巴托的隧道，北上来到这里，在鹰巢山的地面上建起了家园。",
		full = "三锤之战后，蛮锤矮人放弃了他们在格瑞姆巴托的隧道，北上来到这里，在鹰巢山的地面上建起了家园。他们从岩石与熔炉转向了天空与羽翼，与这一带的野生狮鹫结下了极为紧密的羁绊，甚至在自己的城中竖起了一座巨大的狮鹫石像，以纪念这份情谊。早已占据这片土地的森林巨魔，是曾经强盛一时的阿曼尼帝国的残余，他们视矮人为侵占祖先土地的外来者，一有机会就袭击狮鹫栖地。\n\n第二次战争中部落席卷而来，此前对这些入侵者一无所知的领主库德兰·蛮锤和他的骑手们挥舞着蕴含风暴之力的战锤，从天而降扑向兽人的行军队伍，不停地追击骚扰他们。奥格瑞姆·毁灭之锤原本希望将联盟的主力引入辛特兰，以便他能不受阻挡地进攻奎尔萨拉斯，但安度因·洛萨看穿了他的计划，亲自赶到库德兰身边，二人合力击溃了入侵者，将他们一路赶回了奥特兰克山脉。为此，库德兰承诺他的人民将援助联盟。",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "丹莫罗",
		short = "丹莫罗积雪深厚，四面都被卡兹莫丹的群山环绕，山口始终有矮人部队把守。",
		full = "丹莫罗积雪深厚，四面都被卡兹莫丹的群山环绕，山口始终有矮人部队把守。在这些山脉归属于任何人之前，它们属于霜鬃冰巨魔，这些巨魔在远古时代脱离了古拉卡帝国，定居于此。\n\n当第一批侏儒从奥达曼中爬出来，运用他们的智慧来抵御严寒和巨魔，在山峰深处挖掘出坚固的住所时，一切都改变了。五百年后，矮人也随之走出了奥达曼，他们被曾在地平线上远远望见的那片群山所吸引，在最高的那座山峰之下建起了铁炉堡。矮人发现侏儒早已在附近定居，两族结下了从未破裂的友谊：矮人出力帮助建造诺莫瑞根，侏儒则与他们分享机械的奥秘。两族的军队联手击溃了霜鬃巨魔，将幸存者赶回山丘之中，彻底终结了巨魔对这片土地的统治。\n\n如今，诺莫瑞根已然覆灭，化为废墟，它的子民只能挤在铁炉堡中避难。",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "灼热峡谷",
		short = "这里曾是一片青翠的土地，属于赤脊山的一部分，直到两百三十多年前，大地本身被撕裂开来。",
		full = "这里曾是一片青翠的土地，属于赤脊山的一部分，直到两百三十多年前，大地本身被撕裂开来。\n\n三锤之战中，黑铁矮人的巫师领主索瑞森寻求一件能够击溃敌人的武器。他与七名最信任的矮人将手伸向世界的深处，召唤了本应永远沉睡的力量。回应他们的并非仆从，而是主宰：古老的炎魔之王拉格纳罗斯。他的苏醒使黑石山拔地而起，方圆数里的土地化为焦黑，黑铁矮人的都城索瑞森也在山下被碾为齑粉。南面被烧焦的平原后来被称为燃烧平原；而北面这道满目疮痍的山谷则成了灼热峡谷。\n\n浩劫之后，并非所有的黑铁矮人都仍然效忠于他们的氏族。其中一部分人脱离出来，自称瑟银兄弟会，并在俯瞰那巨大采掘场的地方建起了瑟银哨塔，那采掘场是他们昔日的同胞在谷底开凿出来的，而他们便在高处注视着黑铁矮人的劳作。",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "燃烧平原",
		short = "燃烧平原的天空始终泛着红光，被黑石山不时的喷发所照亮，脚下的大地也从未冷却。",
		full = "燃烧平原的天空始终泛着红光，被黑石山不时的喷发所照亮，脚下的大地也从未冷却。黑暗之门开启的两百年前，黑铁矮人被逐出铁炉堡，流亡到了这里。他们的巫师领主索瑞森企图召唤元素仆从，以赢得与铜须和蛮锤两大氏族之间的三锤之战。回应他的却不是仆从，而是曾被泰坦放逐的炎魔之王拉格纳罗斯。他的降临熔化了周围的群山，在冲击的中心隆起了一座火山，并毁灭了召唤他的那些矮人。那座新生山峰的北面成了灼热峡谷；南面则成了燃烧平原，从此伤痕累累。\n\n第一次战争期间，兽人定居在火山的山坡上，并在第二次战争中一直将黑石塔作为据点。战后，黑石兽人重返此地，至今仍盘踞于此，恪守着萨尔停战之前那些残暴的旧习。奈法利安麾下的黑龙占据着塔的上层，据说拉格纳罗斯仍潜伏在这一切下方的某处，暗自酝酿着什么。",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "艾尔文森林",
		short = "第一次战争中兽人来袭时，成千上万的兽人穿过艾尔文森林包围了暴风城，使其除了海路之外与外界完全隔绝。",
		full = "第一次战争中兽人来袭时，成千上万的兽人穿过艾尔文森林包围了暴风城，使其除了海路之外与外界完全隔绝。骑士统领安度因·洛萨率领暴风城骑士穿越森林发起冲锋，出其不意地袭击了兽人的后卫部队，将其击溃。这为城市赢得了时间，但还远远不够。酋长黑手很快便攻占了闪金镇和月溪镇，那是部落与国王之间最后的两座城镇，随后暴风要塞惨遭洗劫。洛萨带领幸存者从海路撤往洛丹伦，城市的废墟一度归暴掠氏族所有。零散的兽人投石车至今仍破损腐朽地散落在这一带，它们是那段占领时期仅存的见证。\n\n城东的北郡农场曾是暴风城农民的骄傲。石匠工会花了数年时间重建被毁的都城，却一直没有得到报酬，而贵族们宁可解散工会也不愿偿还欠款。会长艾德温·范克里夫的怒火演变成了一场暴乱，暴乱夺去了蒂芬·艾莉安·乌瑞恩王后的生命，也催生了迪菲亚兄弟会。兄弟会将农民赶出了北郡，占据了那里的田地。",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "逆风小径",
		short = "逆风小径穿过艾泽拉斯中部的群山，连接着暮色森林与悲伤沼泽。二十年前，这里还被视为赤脊山的一部分。",
		full = "逆风小径穿过艾泽拉斯中部的群山，连接着暮色森林与悲伤沼泽。二十年前，这里还被视为赤脊山的一部分。\n\n卡拉赞的象牙塔曾是黑暗巫师麦迪文的权力中心，它矗立在这片嶙峋之地的中央，不断向土地中渗出邪恶的魔法。树木都已石化，枝叶尽落，一阵可怕的狂风在峡谷中呼啸哀鸣。食人魔、恶魔、亡灵和少数人类吉普赛人在内陆游荡；还有传言说，一股新的势力已经占据了象牙塔，而食人魔和恶魔都已受其操控。",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "暮色森林",
		short = "一层反常的夜幕笼罩着暮色森林，而且从未散去。",
		full = "一层反常的夜幕笼罩着暮色森林，而且从未散去。这里曾是艾尔文森林中秀美的一隅，如今却成了一片受诅咒的垂死之地：树木在黑雾下长得扭曲虬结，死者从坟墓中爬起，狼人也伴随着黑暗悄然潜入，它们是被艾露恩之镰的力量吸引而来的。从逆风小径步步进逼的食人魔更是让这里雪上加霜。\n\n暴风城的庇护早已在这里失去了意义，留下来的人们也学会了在没有庇护的情况下坚守阵地。他们的民兵组织守夜人巡逻着道路，保卫夜色镇不受暗影中任何东西的侵袭：骷髅战士和食尸鬼，凶猛的狼人，还有迪菲亚的人马。\n\n森林的中心是一座早已死去的火山口，笼罩在一片比周围的黑暗更为柔和的暮光之中。那里矗立着一棵伟大之树，它的根须延伸向翡翠梦境，沉睡德鲁伊们的影响为附近生长的一切都染上了色彩。再往外则是废弃的农庄和绵延广阔的乌鸦岭墓地，自从黑暗降临以来，墓地一年比一年更加拥挤。",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "洛克莫丹",
		short = "洛克莫丹的湖水静卧在灰色的岩石之间，被巨石水坝拦蓄着。",
		full = "洛克莫丹的湖水静卧在灰色的岩石之间，被巨石水坝拦蓄着。这座水坝是矮人工程的杰作，艾泽拉斯上再没有任何建筑能与之媲美。群山在四周陡然耸立，零星生长着松树和白桦，湖面则平静而安宁，仿佛从未受过任何惊扰。\n\n这片湖泊曾是一处战场。第二次战争中，部落的兽人席卷这一地区，在这里与联盟展开了决战。铁炉堡守住了。矮人们击退了兽人，收复了洛克莫丹，而那场战争留下的残骸从未被彻底清理：破损的投石车和碎裂的弩车至今仍散落在湖底和湖中的岛屿上，半沉在水中，它们是这片平静的湖水曾是一处杀戮战场的唯一证明。",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "赤脊山",
		short = "赤脊山位于艾尔文森林以东、暮色森林东北，以及燃烧平原以南。",
		full = "赤脊山位于艾尔文森林以东、暮色森林东北，以及燃烧平原以南。\n\n赤脊山是一片田园诗般的地区，河水奔流，榆树参天，地势逐渐升高，它处于暴风城的保护之下，但自第二次战争以来，名义上一直是独立的。这里仍是艾泽拉斯最后几片宁静的土地之一，居民们平和而知足，为暴风城提供木材、鱼类和农作物。然而这份和平并不完美：一支来自燃烧平原的黑石兽人部队占据了石堡要塞，虽然到目前为止他们还算安分。与西部荒野的满目疮痍相比，赤脊山依然还维持着完整。\n\n止水湖的北岸坐落着湖畔镇，它正遭受着周围山丘中豺狼人和黑石兽人的围攻。在它的南边，名为三角路口的十字路口将湖畔镇与艾尔文森林和暮色森林连接起来，并经由湖边大道通往石堡要塞，而这条道路已被雏龙、豺狼人、鱼人和野兽所占据。\n\n湖面看起来十分平静，但鱼人却潜伏在水下，而且一直有传言说，湖底深处藏着一头海怪。",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "荆棘谷",
		short = "荆棘谷是暮色森林南边的一片广袤丛林。丛林巨魔在这片湿热的雨林中巡逻，纳迦在沿岸捕猎，而荆棘藤蔓和凶猛的野兽则让旅途险象环生。",
		full = "荆棘谷是暮色森林南边的一片广袤丛林。丛林巨魔在这片湿热的雨林中巡逻，纳迦在沿岸捕猎，而荆棘藤蔓和凶猛的野兽则让旅途险象环生。\n\n这片山谷曾是古拉巴什帝国的中心，帝国的宏伟城市遍布整个地区。帝国覆灭之后，那些城市渐渐崩塌成废墟，但仍有巨魔居住其中。位于东北部的祖尔格拉布曾是古拉巴什帝国的都城。\n\n藏宝海湾原本是人类定居的一座小港镇，直到被巨魔攻占。后来，热砂集团的地精将巨魔赶出了海湾，据为己有，并将其建成了他们在东部王国的活动中心。\n\n北部矗立着库尔森上校的远征队建起的一座营地。在那里，上校的心智被一个名叫麦佐斯的食人魔法师所控制，他利用一件名为心灵之眼的神器扭曲了库尔森的意志，并借此指挥他的部下。库尔森的一部分士兵起身反抗他们被控制的指挥官，向西逃去，建起了一座反抗军营地，与他公然对抗。",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "悲伤沼泽",
		short = "沼泽的黑水之下，沉睡着一座神庙，它比为这片土地命名的悲伤更加古老。",
		full = "沼泽的黑水之下，沉睡着一座神庙，它比为这片土地命名的悲伤更加古老。古拉巴什帝国覆灭之后，一群名为阿塔莱的叛变巨魔逃进了沼泽，建起了阿塔哈卡神庙，在那里举行骇人的仪式，企图将他们的黑暗洛阿神灵——夺魂者哈卡召回这个世界。他们的魔法扭曲了神庙周围的植物和野兽，直到这种腐化再也无法被忽视。梦境之王伊瑟拉得知了这个教派的野心，便动用她的力量对付他们，赶在哈卡重返世间之前，将神庙沉入了最大的一片沼泽之下。但她并不相信巨魔会永远放弃他们的神灵。她派她的伴侣伊兰尼库斯率领一群绿龙永远守望着这座废墟，使它再也不能被用来向世界释放如此邪恶的力量。绿龙的龙人至今仍奉她之命在这片沼泽中巡逻，而沉没的神庙依然封存在水下，被严密看守，却未被摧毁。",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "西部荒野",
		short = "如今，风毫无阻碍地吹过西部荒野的田野，因为这里已经没有任何高大的东西可以挡住它了。这里曾是暴风城的粮仓，世世代代哺育着这个年轻的王国。",
		full = "如今，风毫无阻碍地吹过西部荒野的田野，因为这里已经没有任何高大的东西可以挡住它了。这里曾是暴风城的粮仓，世世代代哺育着这个年轻的王国。\n\n第二次战争之后，石匠工会重建了暴风城，却没有得到报酬，而卫兵也对他们的抗议兵戎相向。会长艾德温·范克里夫宁可带着他的手下躲进乡间，也不愿面对瓦里安国王的审判。他们在那里成了迪菲亚兄弟会。在月溪镇的一座谷仓下面，范克里夫发现了一条古老的矿道网络，它深得足以掩藏一件武器的建造，而那件武器是用来从海上焚毁暴风城的。他赶走了农民，雇佣河爪豺狼人把守这片土地，并让手下焚烧田地、在土壤中撒盐，让这里再也长不出任何东西。\n\n国库空虚的暴风城任由西部荒野自生自灭。只有格里安·斯托曼挺身而出，在没有任何军队前来援助的情况下，在哨兵岭组建了人民军。\n\n被他撒了盐的田地至今仍未原谅西部荒野。曾经麦浪齐肩的地方，如今只长着稀疏枯黄的野草。",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "湿地",
		short = "水坝下方是一片寒冷灰暗的沼泽，河流与池塘上雾气缭绕，三面环山，西面则向大海敞开。",
		full = "水坝下方是一片寒冷灰暗的沼泽，河流与池塘上雾气缭绕，三面环山，西面则向大海敞开。这里散落着瓦砾，那是曾经占据这片土地的矮人要塞的残迹。如今占据这里的是鱼人、野兽和叛变的兽人，而米奈希尔港是联盟在此唯一真正的立足点。\n\n这座港口并非一直属于联盟。第二次战争开始时，奥格瑞姆·毁灭之锤在巴拉丁海湾中的一座小岛上建造了他的入侵舰队，这样他的船只就能绕开洛丹伦的地面防御，直接攻击其海岸。湿地为此付出了代价：兽人和巨龙大肆掠食这片土地，猎物变得日渐稀少。战后，港口得以重建，并为纪念泰瑞纳斯·米奈希尔二世而更名为米奈希尔港。\n\n随后，格瑞姆巴托也陷落了。红龙军团曾被奴役，为盘踞在那里的龙喉氏族效力，一旦获得自由，便向俘虏它们的人发起了反击，龙喉氏族被彻底击溃，幸存者四散逃入荒野。阿莱克丝塔萨认为，封锁这座山是她的龙族应尽的责任，从那以后，红色龙族便一直在此守望。",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "泰达希尔",
		short = "当玛法里奥·怒风消失在翡翠梦境之中后，大德鲁伊范达尔·鹿盔继而领导塞纳里奥议会，并说服了古树议会，认为种植一棵新的世界之树、重获暗夜精灵所失去的永生的时机已经到来。",
		full = "当玛法里奥·怒风消失在翡翠梦境之中后，大德鲁伊范达尔·鹿盔继而领导塞纳里奥议会，并说服了古树议会，认为种植一棵新的世界之树、重获暗夜精灵所失去的永生的时机已经到来。他们在迷雾之海中种下了泰达希尔，意为大地之冠，并在它的枝干间建起了达纳苏斯。然而曾为第一棵世界之树赐福的诺兹多姆却拒绝祝福这一棵，称这个愿望狂妄自大，而暗夜精灵所追求的永生也始终没有到来。\n\n随着时间推移，泰达希尔顶上的土地被一股邪恶的存在所笼罩。森林中的熊怪和格雷尔陷入疯狂，萨特出现在林间，而曾经在巨树周围的水域中遨游的巨龟和长尾鲨也纷纷逃离，冲上黑海岸的海滩搁浅死去。这场腐化的根源至今仍是个谜，而玛法里奥也没有从梦境中归来查明真相。",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "黑海岸",
		short = "这片海岸上常常笼罩着灰色的雾气，暗夜精灵很久以来都把它视为一种警告。",
		full = "这片海岸上常常笼罩着灰色的雾气，暗夜精灵很久以来都把它视为一种警告。雨水和岩石让这片土地很不宜居，除了奥伯丁这座贸易站之外，任何在此定居的尝试都以失败告终。\n\n一万年前，亚米萨兰和巴莎兰这对双子城坐落于此，由阿斯利库斯·纳拉辛统治。当上古战争撕裂了世界、大分裂随之到来时，阿斯利库斯向他的子民发誓，他会拯救他们。他信守了诺言的字面意思，却背弃了它的本意：他将子民们的灵魂封进灵魂宝石，告诉他们这就是永生，而实际上却吸取他们来滋养自己的力量。两座城市沦为废墟，如今在那些石块间游荡的东西，并未完全安息。\n\n第三次战争之后，范达尔·鹿盔带领塞纳里奥议会的德鲁伊来到黑海岸，在这片海岸上种下了一棵新的世界之树，泰达希尔。",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "灰谷",
		short = "灰谷是一片古老的森林，古树参天，古老的魔法弥漫其间，而围绕它的争夺从未停止。",
		full = "灰谷是一片古老的森林，古树参天，古老的魔法弥漫其间，而围绕它的争夺从未停止。\n\n战歌氏族的兽人最初是作为伐木工来到这里的。尼洛克·贪指手下的地精大肆砍伐树木，直到当地的熊怪将他们击退，而格罗玛什·地狱咆哮为了保住地精的援助，又接连击溃了熊怪和哨兵。塞纳留斯亲自前来，要让被砍伐的一切恢复原貌，却为此付出了生命的代价：燃烧军团的主宰们将他的信任变成了一个陷阱，格罗玛什将他斩杀。\n\n更糟糕的事情还在后头，燃烧军团全力向灰谷进军。阿克蒙德的地狱火熊熊燃烧着从天而降，亡灵和恶魔从东方席卷而来，压垮了暗夜精灵、兽人和人类各自为战的军队，随后继续向海加尔山挺进。泰兰德·语风将玛法里奥从翡翠梦境中唤醒，而他却发现记忆中的森林已被邪能之火吞噬，被令人窒息的枯萎所笼罩。\n\n那场古老的争夺从未结束。暗夜精灵仍然坚守着阿斯特兰纳和他们零散的避难所；部落则将战歌营地深深扎进了南部和东部，砍伐木材，将哨兵步步逼退。双方都未曾真正结束这场争夺森林的战斗。",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "千针石林",
		short = "峡谷又深又干，谷底隐没在高耸的台地之间，直到在东方豁然开朗，化作闪光平原，那是广阔天空下一片巨大的盐滩。",
		full = "峡谷又深又干，谷底隐没在高耸的台地之间，直到在东方豁然开朗，化作闪光平原，那是广阔天空下一片巨大的盐滩。在如此荒凉的土地上，从乱风岗或黑云峰周围的高处眺望日出，是一番壮丽的景象。德鲁伊奎恩丁一直怀疑，这里严酷的干旱紧挨着邻近菲拉斯的茂密丛林，恐怕根本不是自然形成的，而是某种奇异的魔法在这片土地上留下的印记。\n\n高耸的台地属于牛头人，乱风岗便是他们在其间的据点。他们守住这片土地并非毫无挑战。当地的半人马不断进逼，更糟的是，他们自己的同胞恐怖图腾部族也倒戈相向，乱风岗的牛头人不得不为了争夺高地而与同族兵戈相见。直到有了部落的援助，他们才击退了半人马和恐怖图腾。",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "石爪山脉",
		short = "石爪峰在属于任何民族之前，始终属于灵魂。",
		full = "石爪峰在属于任何民族之前，始终属于灵魂。暗夜精灵在峰顶守护着一座古墓和一片林间空地，在那里与自然交流；牛头人也将其视为圣地，因为不朽的先知曾在这里注视着大地之母编织的命运之线。传说中，第一批定居这片山脉的牛头人将燃烧的图腾扛上了最高的峭壁，为安舍点燃篝火，以驱散笼罩在岩石上的黑暗。\n\n在山的较低处，艾露恩很久以前曾为一眼泉水赐下了治愈的恩赐。后来，鹰身人占据了附近的山峰，捕获了在那里筑巢的双足飞龙，并污染了泉水。萨尔前来讨伐她们，凯恩·血蹄和他的牛头人伴随左右，他们击溃了一伙半人马，赢得了一枚净化雕文，净化了被鹰身人腐化的一切。获得自由的双足飞龙载着他们登上了石爪峰本身。\n\n在南部，与这片土地之间那古老的和平已不复存在。风险投资公司将狂风峭壁搜刮得一干二净，砍光树木，让煤烟遮蔽天空，用油污和废料污染水源，直到山中的灵魂发出强烈的悲鸣，就连远在奥格瑞玛的萨满祭司都能听见。",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "凄凉之地",
		short = "石母塞拉赞恩的女儿瑟莱德丝，曾在一片肥沃的草原下沉睡。",
		full = "石母塞拉赞恩的女儿瑟莱德丝，曾在一片肥沃的草原下沉睡。牛头人萨满祭司相信大地之母本人就居住在地下，数十年来一直向她呼唤，直到终于有什么东西作出了回应：那不是大地之母，而是被从沉睡中惊醒、满腔怒火的瑟莱德丝。她吞噬这片土地来恢复自己虚弱的身体，草原在转瞬之间枯死。牛头人将残存下来的土地命名为凄凉之地。\n\n森林之王塞纳留斯的儿子扎尔塔前来束缚她，却爱上了她，而她也爱上了他。半人马便是他们结合的产物，而半人马的第一个举动就是谋杀了自己的父亲。他们迅速繁衍，将牛头人赶出了这片土地，从此开启了两族之间长达数百年的战争。\n\n瑟莱德丝至今仍居住在西部峡谷下方的玛拉顿，半人马也将那里视为他们种族的诞生之地。",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "菲拉斯",
		short = "菲拉斯在它的邻居之中显得格外奇特，这是一片古树参天的雨林，而周围的荒原只有漫天的尘土。",
		full = "菲拉斯在它的邻居之中显得格外奇特，这是一片古树参天的雨林，而周围的荒原只有漫天的尘土。精灵的废墟散布在这片绿意之中，被树根和藤蔓吞没了一半，其中最宏伟的便是被埋葬的城市厄运之槌。\n\n如今戈杜尼食人魔占据着菲拉斯，而他们是通过破坏它来将其据为己有的。他们砍倒了大片大片的森林，他们带来的污秽像疾病一样笼罩着这片土地。在厄运之槌的城墙之外，他们的掠夺队伍在南部的森林中焚烧村庄、谋杀旅人，这股在荒野中蔓延的腐化，可以追溯到地下的废墟。\n\n恐怖图腾牛头人仍零散地居住在这一地区，被那些记得该部族所作所为的人们追猎着。",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "尘泥沼泽",
		short = "这里的蚊子从不停歇，泥泞也是如此。",
		full = "这里的蚊子从不停歇，泥泞也是如此。树木将枝叶在水面上方纠结得如此浓密，以至于阳光洒下时已支离破碎；在海水与沼泽交汇的咸水浅滩中，鳄鱼和鱼人静静等待着。在南部，黑龙大量聚集，人们干脆把那里称作巨龙沼泽。\n\n吉安娜·普罗德摩尔在这片荒野中建立了第一个真正的家园，她在海加尔山之战后带领她的人民来到这里，在沼泽中的岩石岛上建立了塞拉摩。她的城墙熠熠生辉，却也将她困在其中：在通往贫瘠之地道路上零星的哨卡之外，沼泽依旧一如既往地荒野，而她的守军也因悄无声息的逃亡而日渐减少，没有人能解释其中的原因。\n\n也正是在这里，部落与联盟之间的和平彻底破裂。海军上将戴林·普罗德摩尔率领库尔提拉斯舰队在沼泽中进攻部落，随后的冲突以他的死亡告终，停战也就此化为公开的敌对。\n\n蕨墙村矗立在石槌食人魔向部落敞开大门的地方。在它之外，通往贫瘠之地的道路空无一人、日渐荒废，只有迅猛龙和蜘蛛在注视着这片它们一直占据着的土地。",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "塔纳利斯",
		short = "黄沙覆盖了这片曾经是丛林的土地。在世界破碎之前，塔纳利斯一片葱绿，是古拉巴什帝国宣称拥有的领土。",
		full = "黄沙覆盖了这片曾经是丛林的土地。在世界破碎之前，塔纳利斯一片葱绿，是古拉巴什帝国宣称拥有的领土。当大分裂撕裂了大地，丛林随之死去，留下的一切都被烤成了沙丘与岩石。海水退去后，一个巨魔部族发现自己被困在了这里，在随后漫长的岁月里，他们的身体和生活方式都逐渐屈从于沙漠，直到他们不再是从前的巨魔，而成了沙漠巨魔，也就是沙怒巨魔，一个被困住他们的土地所塑造的种族。\n\n热砂集团的地精选中这片荒原来做生意，建立了加基森和热砂港，因为在卡利姆多允许他们定居的地方中，这片沙漠与他们沉没的故乡最为相似。热砂港的码头伸向远方的岛屿，但地精们将船只留给自己使用，不愿载运其他任何种族渡海。\n\n在沙丘和南部山脉之下，隧道绵延数里，大多未经勘测，那些下去的人并不总能回来讲述他们的发现。",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "艾萨拉",
		short = "一万年来，秋天始终笼罩着艾萨拉，树木在悬崖上燃烧般地泛着橙红色，而悬崖下方便是珊瑚，一座城市仍沉睡其中。",
		full = "一万年来，秋天始终笼罩着艾萨拉，树木在悬崖上燃烧般地泛着橙红色，而悬崖下方便是珊瑚，一座城市仍沉睡其中。艾萨拉曾是暗夜精灵所建造过的最伟大的都市，上古战争爆发后，它的大部分都沉入了大海。几座残破的建筑仍紧紧依附在崖壁上，俯视着水下它们自己的废墟。\n\n很久以后，伊利丹·怒风带着他的纳迦，以及随行的莫戈尔和萨特从海加尔山向北逃窜，他一路横扫艾萨拉的海岸，摧毁了暗夜精灵的港口，使任何人都无法追随他前往萨格拉斯之墓。玛维·影歌和她的守望者紧随其后，清剿了他身后留下的那些疯狂的生物。",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "费伍德森林",
		short = "费伍德森林的树木与其说是在生长，不如说是在溃烂。树皮渗出病态的脓液，树叶发黑卷曲，树下的野生动物也因土壤中的腐化而变得扭曲而饥饿。",
		full = "费伍德森林的树木与其说是在生长，不如说是在溃烂。树皮渗出病态的脓液，树叶发黑卷曲，树下的野生动物也因土壤中的腐化而变得扭曲而饥饿。\n\n这种腐烂并非自然的偶然。当燃烧军团向海加尔山进逼时，阿克蒙德下令摧毁这片森林，以削弱守卫那座山的暗夜精灵，而恐惧魔王提克迪奥斯用一件拥有可怕力量的术士遗物——古尔丹之颅执行了这道命令。这片土地随之从内到外逐渐死去：古树变得腐朽而狂暴，野兽发生变异，大地本身也遭到了毒害。\n\n正是在这里，伊利丹·怒风作出了决定他余生的抉择。当他得知那颗头骨可以被用来对抗它自己造成的腐化时，伊利丹独自进入费伍德森林，斩杀了提克迪奥斯，将那件遗物据为己有。此后他并没有交出它。他对魔法的渴求胜过了他的谨慎，而因为使用了燃烧军团自己的力量，他被自己的兄弟玛法里奥放逐了。",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "安戈洛环形山",
		short = "安戈洛环形山被三片沙漠围隔起来，是深陷在卡利姆多南部的一道绿色伤口，在这里，世界忘记了荒芜。",
		full = "安戈洛环形山被三片沙漠围隔起来，是深陷在卡利姆多南部的一道绿色伤口，在这里，世界忘记了荒芜。比记忆还要古老的恐龙在丛林中穿行，其中一些长到了任何生物都不应达到的体型，大地与火焰的元素生物在它们中间安然行走。在上方的山脊上，矗立着一座座从未有人能够解释的水晶塔。\n\n在流沙之战中，暗夜精灵被一路逼退，穿过这座环形山，退到塔纳利斯沙漠的边缘，而其拉的攻势就在那里被遏止。安戈洛本身的某种东西不肯让入侵者占据这片土地，只是从未有人说清那究竟是什么。\n\n威利德·马绍尔和霍莱伊·马绍尔曾率领一支探险队试图在这里建立据点，但环形山的凶险远远超出了他们的准备。他们的营地被攻破，幸存者逃往高处，在如今被称为马绍尔营地的地方坚守了下来。",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "月光林地",
		short = "月光林地静卧在群山环抱之中，是一片从未遭受腐化的隐秘山谷。",
		full = "月光林地静卧在群山环抱之中，是一片从未遭受腐化的隐秘山谷。它的中心是以女神本人命名的月神湖，在湖畔的永夜港小镇中，牛头人和暗夜精灵相处融洽、从不争吵，他们因对自然的共同崇敬而团结在一起，而月光林地守卫绝不允许这份和睦遭到破坏。\n\n上古战争之时，暗夜精灵在燃烧军团面前濒临覆灭，玛法里奥·怒风正是在那时来到了这片山谷。玛法里奥知道他的人民无法单独取胜，于是他带着泰兰德·语风和他的兄弟伊利丹进入月光林地神圣的寂静之中，恳求塞纳留斯给予援助。半神作出了回应，在大分裂重塑了世界之后，林地的守护者们和曾在此栖身的树妖们都走向了外面的世界。塞纳留斯本人则从未离开，月光林地也成了德鲁伊信仰中最神圣的土地。\n\n在无数的土丘之下，沉睡着历代德鲁伊的圣所，而在月神湖的水底，则沉睡着曾深受艾露恩宠爱的半神奥曼，他睡得并不安稳。",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "希利苏斯",
		short = "这片沙漠位于卡利姆多的西南边缘，是一片碎石与黄沙的荒原，从安戈洛出发沿着宽阔的道路便可抵达。",
		full = "这片沙漠位于卡利姆多的西南边缘，是一片碎石与黄沙的荒原，从安戈洛出发沿着宽阔的道路便可抵达。在它的地表之下，埋藏着阿基尔帝国的遗迹安其拉，暗夜精灵将其中央神殿封印起来，试图阻止某种可怕的东西苏醒。散布在希利苏斯各处的废墟，以及如今在沙地中遍布的异种虫巢穴，都足以证明那道封印并没有守住。\n\n很久以前，其拉人自己被驱赶到甲虫之墙后面，在流沙之战结束后被囚禁在那里。他们的仆从异种虫却仍然自由，数百年来不断繁衍，遍布了整个卡利姆多南部，直到暗夜精灵认定这一威胁已大到无法再坐视不理，转而决定重新打开安其拉之门，完成那道墙只是延缓了的事情。\n\n塞纳里奥议会在塞纳里奥要塞中守望，追踪异种虫虫群的动向，并权衡它们是否已成为任何一个种族都无法独自面对的危险。",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "冬泉谷",
		short = "冬泉谷上覆盖着连绵不断的白雪，即便在南部被恶魔侵占的地方，它的美景也不曾受到打扰。这里曾是许多蓝龙的家园，其中就有玛里苟斯的伴侣哈雷。",
		full = "冬泉谷上覆盖着连绵不断的白雪，即便在南部被恶魔侵占的地方，它的美景也不曾受到打扰。这里曾是许多蓝龙的家园，其中就有玛里苟斯的伴侣哈雷。\n\n一万年前，上层精灵从埃达拉斯的一座神殿中偷走了辛玛洛水晶，随后在这里建起了凯斯利尔城。他们忍不住想要测试它的力量，而当水晶破碎时，它释放出的诅咒吞噬了他们。大分裂完成了水晶开始的毁灭，凯斯利尔沦为废墟。它的死者从未离开。后来，高等精灵从奎尔萨拉斯前来寻找水晶的碎片，同样的疯狂也攫住了他们。如今，他们的鬼魂与他们前来研究的那些亡魂一同在废墟中游荡。\n\n地精占据着山谷中心的永望镇，而暗夜精灵也依然在这里保持着他们自己的守望，守护着一片比两者都更加古老的家园。",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "暴风城",
		short = "在兽人部落将暴风城焚毁之后，年轻的瓦里安国王治下的石匠工会用白色的石头将它重新建起。",
		full = "在兽人部落将暴风城焚毁之后，年轻的瓦里安国王治下的石匠工会用白色的石头将它重新建起。然而当王室的国库因战争债务而耗尽，贵族们又拒绝支付工会的报酬时，会长艾德温·范克里夫的抗议换来的却是工会的解散。暴乱随之而来，蒂芬·乌瑞恩王后在混乱中遇害。瓦里安的怒火将石匠们驱逐到西部荒野，他们在那里成了迪菲亚兄弟会；而在王座背后，一个名叫卡特拉娜·普瑞斯托的谋士为了自己的目的，悄悄地挑拨国王与工会反目成仇。\n\n此后，瓦里安国王在可疑的情况下失踪了，在普瑞斯托女士的敦促下，王冠被交给了他年幼的儿子安度因王子，以维持王国的秩序。伯瓦尔·弗塔根公爵担任暴风城的摄政王和军队统帅，而普瑞斯托女士则就王国资源的运用为他出谋划策，在暴风要塞中无人怀疑，也无人质疑。",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "奥格瑞玛",
		short = "奥格瑞玛建立于海加尔山之战后的岁月，那时酋长萨尔带领他的族人来到了卡利姆多一片荒凉的海岸。",
		full = "奥格瑞玛建立于海加尔山之战后的岁月，那时酋长萨尔带领他的族人来到了卡利姆多一片荒凉的海岸。他以父亲的名字将这片土地命名为杜隆塔尔，又以奥格瑞姆·毁灭之锤的名字为他在此建起的城市命名为奥格瑞玛，以纪念这位塑造了他的挚友和导师。城市建得很快，却绝不马虎：坚固的城墙，巨大的城门，高耸的塔楼，背后的群山也被开凿成要塞本身的一部分，让大地亲自守护着这座城市。\n\n建立它的部落，已不再是那个曾经在世界各地烧杀掳掠的部落。恶魔的诅咒被打破后，萨尔的人民从征服转向了生存，而奥格瑞玛的建造不仅依靠兽人，也同样依靠其他种族：地精、牛头人和暗矛巨魔与他们并肩劳作，莫克纳萨尔的雷克萨也为这项工程出了一份力。半人马、鹰身人、雷霆蜥蜴、狗头人和野猪人都曾在这座年轻城市的最初几年中考验过它，但它坚持了下来，不仅成为兽人的家园，也成为巨魔、牛头人，以及后来新近加入部落的被遗忘者的家园。\n\n在这里，就连风也并不友善：锋利如刀的狂风以巨大的力量席卷山谷，足以掀翻那些建造时稍有疏忽的房屋的屋顶。",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "铁炉堡",
		short = "铁炉堡是矮人的首都，开凿在丹莫罗北部铁炉山的深处，它是矮人的祖居之地，也是艾泽拉斯最古老的城市之一。",
		full = "铁炉堡是矮人的首都，开凿在丹莫罗北部铁炉山的深处，它是矮人的祖居之地，也是艾泽拉斯最古老的城市之一。它是卡兹莫丹的都城，由铜须氏族的国王麦格尼·铜须统治。\n\n铁炉堡是一座广阔的地下城市，聚居着工匠、探险家、矿工和战士，以其工业和作为联盟的商业中心而闻名，它既是要塞也是都城，是矮人力量与坚韧的见证。城市由一圈圈同心环构成，越往地下深处，层级越小，全都以位于中心、与城市同名的大锻炉为核心向外辐射。城中满是狭窄的通道、嵌在岩壁中的商店和宽敞如洞窟的房间。这里的气氛热闹、喧嚣而充满工业气息，却又十分温馨；旅店和商店的壁炉中炉火熊熊，到处都能听到矮人的欢笑和嬉闹声。与暴风城和达纳苏斯不同，这座城市是矮人亲手在大地中开凿出的一个巨大洞穴；天花板和地面都是坚硬的岩石。",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "雷霆崖",
		short = "雷霆崖坐落在莫高雷草原上方四座狂风吹拂的台地上，只能乘坐牛头人用绳索和木头制成的升降梯，或经由架设在高地之间的长桥才能抵达。",
		full = "雷霆崖坐落在莫高雷草原上方四座狂风吹拂的台地上，只能乘坐牛头人用绳索和木头制成的升降梯，或经由架设在高地之间的长桥才能抵达。帐篷、长屋和彩绘的图腾遍布在每一座台地的顶端。世世代代以来，牛头人都是游牧民族，一直遭受着在卡利姆多四处游荡的半人马无休止的侵扰。是血蹄部族的酋长凯恩·血蹄终结了这段流亡生涯。第三次战争期间，酋长萨尔和他的新部落来到莫高雷，他们的力量与凯恩的力量合而为一，共同击溃了半人马，终于为牛头人赢得了这片草原。凯恩在台地上建起了一座向每一个流散部族敞开的庇护所，随着时间推移，这些部族作为一个民族臣服于他的统治，他们有时会在前路上意见分歧，却从不怀疑他领导他们的智慧。\n\n这些高崖依然承载着那段建城往事的分量：在一座座高地和一道道长桥之上，在聚集于同一位酋长麾下的各部族的帐篷之中。",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "达纳苏斯",
		short = "暗夜精灵在第三次战争之后建立了达纳苏斯，那时他们长久的永生已离他们而去。许多人无法承受突如其来的衰老与脆弱。",
		full = "暗夜精灵在第三次战争之后建立了达纳苏斯，那时他们长久的永生已离他们而去。许多人无法承受突如其来的衰老与脆弱。一些悲痛的德鲁伊决心种植一棵新的世界之树，以恢复他们与永恒世界之间的联系。由于玛法里奥·怒风下落不明，范达尔·鹿盔接过了大德鲁伊的衣钵，领导了这项工作。他们种下的那棵树，泰达希尔，从海岸边拔地而起，直到树冠冲破云层，暗夜精灵在它的枝干间建立了自己的城市，作为他们种族幸存下来的见证。\n\n达纳苏斯向天空敞开，不同于人类和矮人那些封闭而有城墙环绕的城市。它围绕着一片宽阔的湖泊而建，湖岸之间由优雅的桥梁相连，小径上铺满了落叶。月神殿高耸于树林之上，是高阶女祭司泰兰德·语风和她的艾露恩姐妹会的所在，旁边是柱廊环绕的正义大厅，哨兵们在那里守望。这座城市依然是它当初被建造时的模样：一处宁静的避难所，也是一座纪念碑，纪念一个正在学着与死亡共存的种族。",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "幽暗城",
		short = "早在被遗忘者将其据为己有之前，幽暗城就已有了它的名字和用途。在洛丹伦王宫的地下深处，分布着埋葬王族逝者的古老墓穴、地牢和下水道。",
		full = "早在被遗忘者将其据为己有之前，幽暗城就已有了它的名字和用途。在洛丹伦王宫的地下深处，分布着埋葬王族逝者的古老墓穴、地牢和下水道。这里原本只用来关押囚犯和存放尸体，但洛丹伦最贫穷的百姓们还是挤进了这片黑暗之中，卫兵们一次次的清剿始终无法将他们彻底赶走。\n\n当巫妖王对他所造之物的控制开始松动时，希尔瓦娜斯·风行者带着那些保留了心智的亡灵脱离了天灾军团，并转而对付阿尔萨斯，那个将她变成如今模样的堕落王子。她在这个毁灭的王国中设下陷阱引诱他；他在克尔苏加德的帮助下逃脱，一路北逃，最终成为了巫妖王本身。希尔瓦娜斯和她的追随者成了这片战场的主人，他们自称被遗忘者，占据了残破都城下方的墓穴，并完成了天灾军团早已开始修建的这座要塞。\n\n如今屹立于此的是一座为防御而建的迷宫：有毒的污泥河流贯穿每一条通道，空气中弥漫着活人几乎无法忍受的浓烈烟雾。对于被遗忘者而言，在这个仍在追猎他们的世界里，这里便是他们的栖身之所。",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

